insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('0ce4df0e-821d-406f-870c-72fb75d134eb', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$inleiding: lauwbloedige vissen produceren relatief veel warmte$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context1.png$$,
   $$Sommige vissen zijn ‘lauwbloedig’: ze produceren relatief veel warmte in hun lichaam, waardoor ze warmer zijn dan het koude water waarin ze leven. Welke aanpassingen hebben dergelijke vissen en hoe zijn die in de loop van de evolutie tot stand gekomen? Wetenschappers zoeken naar antwoorden.$$, 'inline'),
  ('7d460994-574c-4b8a-b767-9a0dfb8a5c0c', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$de koningsvis is endotherm en een succesvol jager (afbeelding 1)$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context2.png$$,
   $$De koningsvis (Lampris guttatus, afbeelding 1) is zo’n lauwbloedige (endotherme) vis. Amerikaanse visbiologen hebben ontdekt dat koningsvissen hun temperatuur in vrijwel het hele lichaam ongeveer vijf graden hoger kunnen houden dan hun omgeving.
De koningsvis komt voor in alle wereldzeeën. Hij wordt tot twee meter lang en 60 kilo zwaar. Hij heeft een afgeplatte vorm en beweegt zich voornamelijk voort door bewegingen van de borstvinnen. De koningsvis ziet er misschien niet echt uit als een predator, maar hij is wel degelijk een succesvol jager.
afbeelding 1: foto van een koningsvis die door een visser wordt vastgehouden.$$, 'inline'),
  ('262a19c0-a8eb-432b-9a9e-3a2e0c263bbb', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$endothermie komt alleen bij grote vissoorten voor$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context3.png$$,
   $$Endothermie komt alleen bij grote vissoorten voor.$$, 'inline'),
  ('1b6fee19-cdd2-4bcd-88a1-3e347e4b11f6', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$de koningsvis heeft veel myoglobine in zijn donkerrode spieren$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context4.png$$,
   $$De koningsvis is extreem gespierd en zijn spieren zijn opvallend donkerrood, door een grote hoeveelheid myoglobine.$$, 'inline'),
  ('83c324f8-583c-434d-b6b8-7b7c94a61d7b', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$tabel 1: temperatuur en temperatuurverschil per lichaamsgebied$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context5.png$$,
   $$tabel 1: gemiddelde temperatuur en temperatuurverschil met het zeewater (beide ± standaardafwijking) van verschillende lichaamsgebieden van koningsvissen.
Aan dek gemeten koningsvissen: borstvinspier 13,8 ± 1,5 °C (verschil 3,8 ± 0,8 °C, n=22); hart 13,2 ± 1,7 °C (verschil 3,2 ± 0,7 °C, n=21); schedel 16,1 ± 3,9 °C (verschil 6,0 ± 3,0 °C, n=22); buikholte 13,5 ± 1,6 °C (verschil 3,5 ± 1,0 °C, n=19).
Vrij zwemmende koningsvissen met datarecorder: borstvinspier 14,4 ± 0,4 °C (verschil 4,8 ± 1,2 °C, n=4).$$, 'inline'),
  ('42a0d8a8-4df9-4534-9ff5-b8d592a68d52', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$samentrekking borstvinspier is grootste bron van warmteproductie$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context6.png$$,
   $$Volgens de onderzoekers is de samentrekking van de borstvinspieren de grootste bron van warmteproductie.
In de buikholte wordt veel minder warmte geproduceerd.$$, 'inline'),
  ('ea86afea-62e8-4089-80a5-b94ebd93a076', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$twee uitspraken over de gegevens in tabel 1$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context7.png$$,
   $$Twee uitspraken over de gegevens in tabel 1 zijn:
1 Naast de borstvinspier is er nog een ander gebied waar veel warmte wordt geproduceerd.
2 Uit de grote spreiding in de gemeten temperaturen van de schedel blijkt dat deze metingen niet valide zijn.$$, 'inline'),
  ('aa3a755f-5905-45e6-89ec-f3ee472a0a68', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$meetperiode van drie uur bij een vrij zwemmende koningsvis (afbeelding 2)$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context8.png$$,
   $$In afbeelding 2 staan de resultaten van een meetperiode van ruim drie uur bij één van de vrij zwemmende koningsvissen, uitgerust met een datarecorder.
afbeelding 2: grafiek met drie genummerde lijnen (1, 2 en 3) tegen de tijd (19:00–22:20); de linker y-as toont de temperatuur (°C), de rechter y-as de diepte (m).$$, 'inline'),
  ('5e90d702-d6a8-4b8f-b806-d810b1770bfe', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$de drie lijnen betreffen zwemdiepte, watertemperatuur en borstvinspiertemperatuur$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context9.png$$,
   $$De drie genummerde lijnen in het diagram hebben betrekking op metingen van de zwemdiepte, de watertemperatuur op die diepte en de temperatuur van de borstvinspier.$$, 'inline'),
  ('9c99527a-6626-4f5c-bfb8-ed58d2d70ae7', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$warmtelek via de kieuwen en de bouw van een kieuw (afbeelding 3)$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context10.png$$,
   $$Net als zeehonden en pinguïns hebben ook koningsvissen een onderhuidse vetlaag om warmteverlies in koud water te reduceren.
Vissen hebben echter een enorm ‘warmtelek’ in de kieuwen, waar het bloed door een haarvatennet in nauw contact komt met het koude water. Zonder aanpassingen zouden endotherme vissen hierdoor het overgrote deel van de geproduceerde warmte verliezen.
Afbeelding 3 toont schematisch de bouw van een kieuw. Achter het kieuwdeksel zitten honderden dunne kieuwplaatjes aan halfronde kieuwbogen van bot. Dwars op elk kieuwplaatje staan weer honderden kleine lamellen met haarvaatjes waarin zuurstof uit het passerende water wordt opgenomen en koolstofdioxide uit het bloed wordt afgegeven.
afbeelding 3: schematische tekening van een vis met een uitvergroting van een kieuwboog met kieuwplaatjes; bij de kieuwboog zijn het wondernet (kluwen bloedvaatjes) en het omliggende vetweefsel aangegeven.$$, 'inline'),
  ('baf5f65e-9e59-4d81-b0db-84fe3870f1d8', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$twee aanpassingen die warmteverlies in de kieuwen beperken: wondernet en vetweefsel$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context11.png$$,
   $$De onderzoekers vonden bij koningsvissen twee aanpassingen die het warmteverlies in de kieuwen beperken.
1 In de kieuwbogen ligt een ‘wondernet’: een kluwen van verstrengelde bloedvaatjes waarin het bloed dat naar de kieuwplaatjes gaat steeds vlak naast het bloed stroomt dat vanaf de kieuwplaatjes terug naar het lichaam gaat.
2 Rond de kieuwbogen zit een laagje vetweefsel.$$, 'inline'),
  ('91641fc2-5418-4075-9006-80f279f32a90', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$mtDNA-onderzoek wijst op vijf afstammingslijnen van de koningsvis (afbeelding 4)$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context12.png$$,
   $$Een werknemer van een visgroothandel in Hawaii merkte op dat sommige koningsvissen grotere ogen hadden dan andere. Dat leidde bij geraadpleegde visbiologen tot de hypothese dat de koningsvis niet één soort is. Om dat te onderzoeken sequensten de visbiologen het mtDNA van 480 koningsvissen uit alle wereldzeeën en van de verwante soort Lampris immaculatus.
Op grond van variaties in het CO1-gen (dat codeert voor cytochroom c oxidase1) van de verschillende individuen concludeerden de onderzoekers dat er vijf afstammingslijnen zijn van de koningsvis Lampris guttatus.
Dit is weergegeven in het cladogram van afbeelding 4.
afbeelding 4: cladogram met de verwantschap tussen Lampris immaculatus en de vijf afstammingslijnen (1 t/m 5) van de koningsvis Lampris guttatus, gebaseerd op variatie in het CO1-gen.$$, 'inline'),
  ('3ddea633-3bf2-4b97-8cb7-1e8fd5efb7cf', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$drie beweringen op basis van het cladogram$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context13.png$$,
   $$Op basis van dit cladogram worden drie beweringen gedaan:
1 Lampris immaculatus is de gemeenschappelijke voorouder van alle koningsvissen.
2 Afstammingslijn 2 is meer verwant met 4 dan met 1.
3 Afstammingslijn 3 is meer verwant met 4 dan met 5.$$, 'inline'),
  ('1c75d45d-c981-4fb6-a97c-c089a150064e', '8820e42f-4d5f-44d2-986b-d39ecc504d89', $$discussie over een mogelijke evolutionaire relatie tussen koningsvissen en zoogdieren$$,
   $$biologie-vwo-2018-ii-de-lauwbloedige-koningsvis-context14.png$$,
   $$Op de website van het tijdschrift National Geographic staat een bericht over de warmbloedige koningsvis. Donald reageert daarop: “Ik geloof dit niet! Als deze vis warmbloedig is, is hij dan geëvolueerd uit een zoogdier?” Op school bespreken leerlingen het idee van Donald.
Drie reacties zijn:
1 Als lauwbloedige vissen, net zoals walvissen, uit zoogdieren zouden zijn geëvolueerd, dan zouden ze longen hebben en geen kieuwen.
2 Er heeft co-evolutie plaatsgevonden, waardoor zowel de koningsvissen als de zeezoogdieren endotherm werden en hierin op elkaar lijken.
3 Koningsvissen zijn de lauwbloedige evolutionaire schakel tussen de koudbloedige vissen en de warmbloedige zoogdieren.$$, 'inline'),
  ('1f74185e-027d-4ce5-b956-363f5389388f', 'b872596a-69b1-424b-adf5-244330ec85a7', $$inleiding: Ruth is één van de ruim 10.000 Nederlandse diabetes type 1-patiënten$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context1.png$$,
   $$Ruth is één van de ruim 10.000 Nederlandse diabetes type 1 patiënten jonger dan 25 jaar. Gelukkig voor Ruth is deze vorm van suikerziekte sinds de ontdekking van insuline niet meer levensbedreigend. In het verleden was het onderzoek gericht op het verbeteren van de kwaliteit van de insuline en de wijze van toediening; de uitdaging is nu om diabetes type 1 te genezen.$$, 'inline'),
  ('24dccbee-879c-4618-8989-d00072571de7', 'b872596a-69b1-424b-adf5-244330ec85a7', $$diabetes type 1 is een auto-immuunziekte tegen de β-cellen$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context2.png$$,
   $$Toen Ruth vijf jaar was, kreeg zij de eerste symptomen van diabetes type 1: veel dorst en veel plassen. Meting van de bloedglucosewaarde door de huisarts wees uit dat deze was verhoogd. Ook werd glucose in haar urine aangetoond.
Diabetes type 1 is een auto-immuunziekte. Het immuunsysteem maakt antistoffen tegen de insulineproducerende β-cellen van de eilandjes van Langerhans.$$, 'inline'),
  ('8f20359b-0eba-4c02-9f89-56f4c0c239bb', 'b872596a-69b1-424b-adf5-244330ec85a7', $$insuline-genexpressie in de thymus is lager bij kinderen met diabetes type 1$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context3.png$$,
   $$Tijdens de embryonale ontwikkeling wordt het insuline-gen ook in de thymus afgelezen. In de thymuscellen van kinderen met diabetes type 1 blijkt de expressie van het insuline-gen lager te zijn dan bij gezonde kinderen.$$, 'inline'),
  ('2a618c7b-5855-4016-b85d-09a27dc01aad', 'b872596a-69b1-424b-adf5-244330ec85a7', $$hoge glucosewaarde vermindert via ADH-regulatie de urineproductie$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context4.png$$,
   $$Bij gezonde personen veroorzaakt een tijdelijk hogere glucosewaarde in het bloed via regulatie van de ADH-afgifte een afname van de hoeveelheid geproduceerde urine.$$, 'inline'),
  ('570dbc23-4dee-4048-8e95-29300f4cc413', 'b872596a-69b1-424b-adf5-244330ec85a7', $$insulineschema van Ruth en het dageraadfenomeen (afbeelding 1)$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context5.png$$,
   $$Een hoge glucosewaarde in het bloed (hyperglycemie) is ongezond doordat kleine bloedvaatjes beschadigd worden. Ruth leerde daarom al op jonge leeftijd om vlak voor elke maaltijd een hoeveelheid snelwerkende insuline te injecteren. Daarnaast diende zij zichzelf tweemaal per dag een langzamer werkende insuline toe (afbeelding 1).
afbeelding 1: grafiek van insulineactiviteit tegen de tijd (08:00–08:00) bij injecties met snelwerkende insuline (rond ontbijt, lunch en avondeten) en met langzaamwerkende insuline (rond ontbijt en avondeten), met een foto van een insuline-injectie in de buik.
Ook bij patiënten zoals Ruth die zich goed aan dit schema houden, komt het voor dat de bloedglucosewaarden ernstig schommelen. Zoals een lage bloedglucosewaarde (hypoglycemie) in de nacht en het ‘dageraadfenomeen’: een stijging van de bloedglucosewaarde in de vroege ochtend, vóór het ontbijt.$$, 'inline'),
  ('5969fc5b-9b55-4f45-b5a9-6446defb2310', 'b872596a-69b1-424b-adf5-244330ec85a7', $$insulinepompje en het effect op bloedglucosewaarden gedurende een etmaal (afbeelding 2)$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context6.png$$,
   $$Sinds haar 14e gebruikt Ruth een insulinepompje (afbeelding 2). Het pompje is geprogrammeerd om via een klein naaldje in de buik voortdurend insuline af te geven. Wanneer Ruth eet, berekent het pompje op basis van de koolhydraathoeveelheid die zij invoert, hoeveel insuline er dan extra nodig is (de maaltijdbolus).
De insulinetoediening door het pompje en het effect daarvan op bloedglucosewaarden gedurende een etmaal zijn vereenvoudigd weergegeven in de diagrammen van afbeelding 2.
afbeelding 2: twee gekoppelde diagrammen tegen de tijd (08:00–08:00): boven de insuline-afgifte door het pompje, onder de bijbehorende bloedglucosewaarde (mmol/L), met een foto van een insulinepompje bevestigd aan de buik.$$, 'inline'),
  ('457a0408-b828-4bd6-880b-58e25f79c974', 'b872596a-69b1-424b-adf5-244330ec85a7', $$drie beweringen over het gebruik van een insulinepompje$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context7.png$$,
   $$Op basis van de gegevens over het gebruik van een insulinepompje worden de volgende beweringen gedaan:
1 De bloedglucosewaarden kunnen bij gebruik van een insulinepompje nooit hoger worden dan 10 mmol per liter.
2 De hoeveelheid insuline die het pompje bij het avondeten afgeeft is ongeveer de helft van de hoeveelheid bij de lunch.
3 Gebruik van het insulinepompje voorkomt het dageraadfenomeen.$$, 'inline'),
  ('9a7d82d9-efda-4a80-955e-8749d97cf9ca', 'b872596a-69b1-424b-adf5-244330ec85a7', $$onderzoek naar een implanteerbare capsule met β-cellen uit stamcellen$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context8.png$$,
   $$Er is goede hoop op een doorbraak waardoor Ruth genezen kan worden. Onderzoekers van de universiteiten van Leiden, Maastricht, Utrecht en Eindhoven werken samen aan een onder de huid implanteerbare capsule, een soort theezakje van een gelatineachtige stof, waarin zich insuline producerende β-cellen bevinden. De cellen komen niet van een donor, maar zijn gevormd uit lichaamseigen stamcellen van de patiënt. De capsule voorkomt het optreden van een auto-immuunrespons tegen deze β-cellen.$$, 'inline'),
  ('3074a50f-e494-4bd2-8447-688b45e1c99b', 'b872596a-69b1-424b-adf5-244330ec85a7', $$de poriën van de capsule mogen niet te groot en niet te klein zijn$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context9.png$$,
   $$Voor het succes van deze behandeling is het noodzakelijk dat de capsule die de β-cellen omhult, aan bepaalde eisen voldoet. Zo mogen de poriën erin niet te groot, maar ook niet te klein zijn, zodat bepaalde stoffen wél naar buiten en bepaalde andere stoffen niét naar binnen kunnen.$$, 'inline'),
  ('06f3ef99-1539-4f33-a41e-9fe1e0935ad2', 'b872596a-69b1-424b-adf5-244330ec85a7', $$de gellaag rond de β-cellen mag niet te dik zijn$$,
   $$biologie-vwo-2018-ii-nieuwe-eilandjes-voor-de-alvleesklier-context10.png$$,
   $$Ook mag de gellaag die de β-cellen omhult niet te dik zijn. De diffusieafstand mag het goed functioneren van de β-cellen niet hinderen.$$, 'inline'),
  ('d7121aed-2511-4c20-852b-0677b7f61c17', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$inleiding: verband tussen klachten van grootvaders en verstandelijke beperking kleinkinderen$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context1.png$$,
   $$Duizenden grootvaders liepen rond met onbegrepen neurologische klachten totdat de Amerikaanse kinderarts Randi Hagerman een verband legde tussen de klachten van de grootvaders en de verstandelijke beperking van hun kleinkinderen.$$, 'inline'),
  ('c4fd36c3-7e01-4796-ae09-8d7980c17fa0', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$FXTAS bij grootvaders en FXS bij kleinkinderen door CGG-repeats in het FMR1-gen$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context2.png$$,
   $$De grootvaders waren tot middelbare leeftijd gezond, maar vanaf hun 50ste levensjaar kregen zij geleidelijk meer last van bevingen, motorische problemen en achteruitgang van verstandelijke vermogens. Deze aandoening heet nu het fragiele X-gerelateerde ataxie syndroom (FXTAS). De aandoening van hun zwakbegaafde kleinkinderen wordt het fragiele X-syndroom (FXS) genoemd.
De namen verwijzen naar de ‘fragiele’ plaats op het X-chromosoom die ontstaat door een mutatie in het FMR1-gen, namelijk de toename van het aantal CGG-herhalingen (repeats) aan het begin van het gen. Deze plaats is tijdens een mitose onder een gewone microscoop als een dun stukje van het chromosoom zichtbaar.$$, 'inline'),
  ('d5ab5c82-b281-40b6-9792-6f4f3353add9', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$trinucleotide-repeatmutaties zijn vaak minder ingrijpend dan dinucleotide-repeatmutaties$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context3.png$$,
   $$Mutaties waarbij ergens in een gen een aantal extra repeats ontstaat, komen regelmatig voor. Mutaties waardoor het aantal trinucleotide-repeats (herhalingen van drie nucleotiden) verandert, zijn vaak minder ingrijpend dan die van het aantal dinucleotide-repeats (herhalingen van twee nucleotiden).$$, 'inline'),
  ('f8cfc88a-e531-4190-a713-10e56be0a4a6', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$indeling in normaal, premutatie en volledige mutatie van het FMR1-gen (afbeelding 1)$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context4.png$$,
   $$Direct achter de promotor van het FMR1-gen liggen bij gezonde personen 6 tot 54 CGG-repeats. De volledige mutatie, met meer dan 200 CGG-repeats, leidt tot methylering en heeft FXS tot gevolg. Bij de premutatie, die kan leiden tot symptomen van FXTAS, ligt het aantal repeats tussen de 55 en 200.
Opvallend is dat als gevolg van de premutatie ongewoon veel mRNA gevormd wordt, wat soms leidt tot ophoping van RNA-eiwitcomplexen, waardoor dit RNA nauwelijks getransleerd wordt.
In afbeelding 1 is een indeling van deze mutaties in het FMR1-gen en hun gevolgen in zenuwcellen weergegeven.
afbeelding 1: schema van het FMR1-gen met CGG-repeats, en per situatie (normaal <55 repeats, premutatie 55-200 repeats, volledige mutatie >200 repeats met methylering) de gevolgen voor de hoeveelheid gevormd mRNA, het FMRP-eiwit en het fenotype.$$, 'inline'),
  ('94817fb0-b77a-45fe-b14c-3ecf115197af', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$ophoping van RNA-eiwitcomplexen is toxisch voor zenuwcellen bij de premutatie$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context5.png$$,
   $$De ophoping van RNA-eiwitcomplexen in zenuwcellen van iemand met de premutatie heeft een toxisch effect op deze cellen.$$, 'inline'),
  ('d6e7b575-3f63-4cae-a939-1a03ebe4b07f', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$vrouwen met heterozygote premutatie kunnen door willekeurige X-inactivatie toch FXTAS-symptomen krijgen$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context6.png$$,
   $$Hoewel de premutatie recessief is, kunnen vrouwen met een heterozygoot genotype toch symptomen van FXTAS krijgen. Dit hangt samen met het feit dat bij hen in elke cel willekeurig één van de twee X-chromosomen geïnactiveerd is.$$, 'inline'),
  ('1c17bf58-b1d1-41c8-9ea5-a62acd477b78', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$stamboom van een familie met FXS en FXTAS, met CGG-repeataantallen (afbeelding 2)$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context7.png$$,
   $$In afbeelding 2 is een stamboom weergegeven van een familie waarin de aandoeningen FXS en FXTAS voorkomen. De getallen onder de symbolen van de familieleden geven het aantal CGG-repeats in het FMR1-gen op de X-chromosomen aan.
afbeelding 2: stamboom van een familie over vijf generaties (I t/m V), met bij elk familielid het aantal CGG-repeats in het FMR1-gen vermeld (bijvoorbeeld II-1: 120 repeats, IV-2: 30/252 repeats, V-2: 406 repeats); een volledig gekleurd symbool geeft een volledige mutatie aan, een symbool met stip een premutatie.
Als het aantal CGG-repeats groter is dan 55, is het aantal dat aan de volgende generatie wordt doorgegeven vaak niet stabiel. Er kan dan zowel afname als toename van het aantal repeats plaatsvinden.$$, 'inline'),
  ('ce624660-274e-43f9-9230-ebcd4a683e15', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$de premutatie kan in één generatie leiden tot een volledige mutatie in de volgende$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context8.png$$,
   $$Uit de stamboom (afbeelding 2) is af te leiden dat de premutatie in één generatie kan leiden tot een volledige mutatie in de daaropvolgende generatie.$$, 'inline'),
  ('13ab8414-a7cb-4239-ac4f-ef4dfd856f9b', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$de diagnose FXTAS bij grootvaders kwam aan het licht via de FXS-diagnose van hun kleinkinderen$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context9.png$$,
   $$De diagnose FXTAS bij grootvaders is aan het licht gekomen door de verstandelijke beperking van hun kleinkinderen met FXS.$$, 'inline'),
  ('203a226a-ea69-40f1-a56b-eb9cc588eafa', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$locus van het FMR1-gen op het X-chromosoom (afbeelding 3)$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context10.png$$,
   $$De locus van het FMR1-gen is Xq27.3 (q-arm van het X-chromosoom, positie 27.3). In afbeelding 3 is het X-chromosoom met verschillende loci afgebeeld.
afbeelding 3: schema van het X-chromosoom met de p-arm en de q-arm, onderverdeeld in genummerde loci (banden); de locus Xq27.3 (het FMR1-gen) ligt op de q-arm.$$, 'inline'),
  ('f251932b-8764-4da4-876f-1bf6b45462d1', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$X-chromosomen onder de lichtmicroscoop, met de fragiele plek als insnoering (afbeelding 4)$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context11.png$$,
   $$In afbeelding 4 zijn X-chromosomen getekend die onder een gewone lichtmicroscoop te zien kunnen zijn. De fragiele plek is in een chromosoom met een volledige FMR1-mutatie als een insnoering zichtbaar.
afbeelding 4: vijf genummerde tekeningen (1 t/m 5) van X-chromosomen zoals zichtbaar onder een lichtmicroscoop, met per chromosoom een verschillende vorm van de chromosoomarmen.$$, 'inline'),
  ('ae714833-45be-4ca4-8825-c1e5272088f5', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$ongeveer 30% van de mannen is drager van FXTAS; PCR-techniek bepaalt het aantal CGG-repeats$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context12.png$$,
   $$Ongeveer 30% van de mannen is drager van FXTAS. Om dit aan te tonen is het aantal CGG-repeats in het FMR1-gen bepaald.
Onderdeel van deze FXTAS-test is de PCR-techniek.$$, 'inline'),
  ('f4db51c9-e1e5-4b47-8132-d718f5e0d0c7', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$gelelektroforese-resultaat van een FXTAS-test bij twaalf personen (afbeelding 5)$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context13.png$$,
   $$In afbeelding 5 is het resultaat van een FXTAS-test van twaalf mannen en vrouwen afgebeeld. Van elke persoon zijn stukjes DNA met het FMR1-gen gesorteerd op lengte. Bij een volledige methylering zijn geen bandjes zichtbaar, maar verschijnt er een diffuse streep.
afbeelding 5: gelelektroforese-afbeelding van de FXTAS-test bij twaalf personen (1 t/m 12, plus marker), met DNA-fragmentlengte in basenparen op de y-as. Drie zones zijn aangegeven: <50 herhalingen/normaal (<300 bp), 50-199 herhalingen/premutatie (300-1000 bp) en ≥200 herhalingen/volledige mutatie (>1000 bp, zichtbaar als diffuse streep bij methylering). De banden van de verschillende personen liggen op wisselende hoogtes in deze drie zones.$$, 'inline'),
  ('dc4ddb32-d135-46c3-99cd-29e037edc48f', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$knock-out-muizen zonder FMRP tonen vertraagde hersenschorsontwikkeling en leer-/geheugenproblemen$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context16.png$$,
   $$Uit onderzoek bleek dat bij knock-out-muizen die het eiwit FMRP niet maken, de ontwikkeling van de hersenschors in de embryonale fase wordt vertraagd. Na de geboorte leidt het ontbreken van FMRP tot veranderingen in synapsen in de hersenen waardoor leer- en geheugenproblemen ontstaan.$$, 'inline'),
  ('3180bf0f-22be-4a54-b163-debf57bcd14f', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$versterking van synapsen tijdens leren via glutamaatreceptoren; synaps bij FXS (afbeelding 6)$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context14.png$$,
   $$Normaliter worden tijdens het leren de contacten tussen zenuwcellen in de hersenen sterker door de vermeerdering van receptoren voor neurotransmitters in het celmembraan. Zo leidt stimulering van bepaalde glutamaatreceptoren (mGluR5) tot de synthese van eiwitten die de hoeveelheid van andere glutamaatreceptoren (AMPA) van zenuwcellen in het celmembraan beïnvloeden.
In afbeelding 6 is links een normaal functionerende synaps in de hersenen weergegeven, rechts een synaps van iemand met FXS.
afbeelding 6: schema van twee synapsen (glutamaat, mGluR5-receptor, AMPA-receptor, eiwitsynthese en het eiwit FMRP), links van een normaal functionerende synaps, rechts van een synaps bij iemand met het fragiele-X-syndroom (FXS); de twee schema's tonen een verschil in de regulatie van de eiwitsynthese door FMRP tussen de twee situaties.$$, 'inline'),
  ('d41bf3ce-ecb7-4ea9-80cb-5f2a05f4042e', '97772fe9-15ad-4ef9-b3c9-014ae399ad14', $$onderzoekers hopen een medicijn te vinden tegen symptomen van FXS$$,
   $$biologie-vwo-2018-ii-een-bijzondere-band-tussen-grootvader-en-kleinkind-context15.png$$,
   $$Onderzoekers hopen een medicijn te vinden dat de symptomen van FXS kan verminderen.$$, 'inline'),
  ('ff471923-18d0-4adc-83be-e6c2b9e2938d', 'd37ed251-aa62-4958-8b36-bfc5b40b5af5', $$inleiding: waterstofgas als CO2-neutraal alternatief voor fossiele brandstoffen$$,
   $$biologie-vwo-2018-ii-biologische-productie-van-waterstofgas-context1.png$$,
   $$Vanwege de opwarming van de aarde wordt naarstig gezocht naar alternatieven voor fossiele brandstoffen. Waterstofgas (H₂) is zo’n alternatief, want bij de verbranding van H₂ komt uitsluitend water vrij. De industriële productie van dit gas is echter nog verre van CO₂-neutraal.$$, 'inline'),
  ('773b06dd-9be5-4776-922c-6e75339df5a0', 'd37ed251-aa62-4958-8b36-bfc5b40b5af5', $$opstelling met twee reactoren voor biologische waterstofproductie (afbeelding 1)$$,
   $$biologie-vwo-2018-ii-biologische-productie-van-waterstofgas-context2.png$$,
   $$Door de inzet van H₂-producerende bacteriën is het in de toekomst misschien wel mogelijk om op een milieuvriendelijke wijze waterstofgas te produceren. Een opstelling hiervoor met twee reactoren wordt getest door procestechnologen.
In de eerste reactor zetten bacteriën organische stoffen (bijvoorbeeld uit aardappelschillen) om in organische zuren, H₂ en CO₂. In een tweede reactor worden de organische zuren onder invloed van licht door andere bacteriën omgezet in nog meer H₂ en CO₂. Een schematische weergave van deze opstelling is te zien in afbeelding 1.
afbeelding 1: schema van een proefopstelling met twee gekoppelde reactoren; reactor 1 bevat organische stoffen die door bacteriën worden omgezet tot organische zuren plus H₂ en CO₂, reactor 2 bevat deze organische zuren die onder invloed van licht door andere bacteriën worden omgezet tot nog meer H₂ en CO₂; het gevormde gas gaat naar een gasopvang en vervolgens een gasscheider die H₂ afscheidt, biomassa wordt aangevoerd naar reactor 1.$$, 'inline'),
  ('d86d9b08-3fd9-46b0-a90e-18d26a4f0372', 'd37ed251-aa62-4958-8b36-bfc5b40b5af5', $$doel van het testprogramma: geschikte biomassa vinden, zoals aardappelschillen met polysachariden$$,
   $$biologie-vwo-2018-ii-biologische-productie-van-waterstofgas-context3.png$$,
   $$Doel van het testprogramma is het optimaliseren van het proces, onder andere door een geschikte vorm van biomassa te vinden. Zo is er geëxperimenteerd met aardappelschillen, een restproduct van de industriële verwerking van aardappelen tot frites. Dit restproduct bevat verschillende typen polysachariden.$$, 'inline'),
  ('c35dde78-49c0-4fbe-9a70-470adde2cfce', 'd37ed251-aa62-4958-8b36-bfc5b40b5af5', $$Caldicellulosiruptor saccharolyticus met hydrogenase-enzym voor reactor 1$$,
   $$biologie-vwo-2018-ii-biologische-productie-van-waterstofgas-context4.png$$,
   $$Een ander onderdeel van het testprogramma is het selecteren van geschikte micro-organismen. Voor reactor 1 lijkt de anaerobe thermofiele Caldicellulosiruptor saccharolyticus een geschikte kandidaat. Deze bacterie bevat het enzym hydrogenase dat in reactor 1 de onderstaande reactie versnelt:
H⁺ + NADH → H₂ + NAD⁺$$, 'inline'),
  ('b8792dff-5018-483b-8f2b-6ae9234f63a0', 'd37ed251-aa62-4958-8b36-bfc5b40b5af5', $$purperbacteriën in reactor 2 verbruiken geen CO2 door aanwezigheid van organische zuren$$,
   $$biologie-vwo-2018-ii-biologische-productie-van-waterstofgas-context5.png$$,
   $$Bacteriën kunnen chemo-autotroof, chemo-heterotroof, foto-autotroof of foto-heterotroof zijn.
Door de aanwezigheid van organische zuren in reactor 2 wordt er in de daar aanwezige purperbacteriën geen CO₂ verbruikt.$$, 'inline'),
  ('1a3c9421-1b8d-4521-83fd-b9da209b21a7', 'd37ed251-aa62-4958-8b36-bfc5b40b5af5', $$in beide reactoren komt CO2 vrij$$,
   $$biologie-vwo-2018-ii-biologische-productie-van-waterstofgas-context6.png$$,
   $$In beide reactoren van de proefopstelling (afbeelding 1) komt CO₂ vrij.$$, 'inline'),
  ('0ceff006-40e4-4ecb-ab8b-52baf1ab4121', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$muizenplaag in Friesland in 2014-2015; veldmuizen en hun levenswijze (afbeelding 1, 2)$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context1.png$$,
   $$In 2014 en 2015 was er in Friesland veel schade door grote aantallen veldmuizen (afbeelding 1). Graslanden die er in augustus nog goed uitzagen, waren in maart kaal en vol met muizengangen (afbeelding 2).
In opdracht van verschillende organisaties, zoals het Wetterskip Fryslân, onderzochten ecologen hoe de veldmuizenpopulaties te beheersen zijn.
afbeelding 1: foto van een veldmuis die wordt vastgehouden.
afbeelding 2: twee foto's van grasland, met muizengangen en vraatschade zichtbaar.
Veldmuizen (Microtus arvalis) leven bij voorkeur in graslanden, wegbermen, slootkanten en dijken, waar ze eten van de grassen en kruiden. Ze graven meterslange gangenstelsels in de grond, met diepliggende nesten en voorraadkamers.
De populatiegrootte varieert gedurende het jaar.
Omdat de meeste veldmuizen de winter niet overleven zijn de aantallen in het voorjaar relatief klein. In de zomer, wanneer de omstandigheden gunstiger zijn en het gras hard groeit, neemt de populatie snel toe. Als dan in het najaar ook de nieuwe generaties veldmuizen aan de voortplanting deelnemen, kan de toename enorm zijn. Soms komen er zo veel veldmuizen dat ze zich ook vestigen in landbouwpercelen, waar ze eten van de gewassen die er groeien.$$, 'inline'),
  ('bc80113c-b6df-47d9-af13-993ba7e2ec99', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$er is een grens aan het aantal individuen dat een gebied langdurig kan handhaven$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context2.png$$,
   $$Er is een grens aan het aantal individuen van een soort dat zich in een bepaald gebied langdurig kan handhaven.$$, 'inline'),
  ('87a0ff68-0612-4077-842c-f631a9dfedf2', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$onder water zetten van het land tijdens het hoogtepunt van de plaag hielp onvoldoende$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context3.png$$,
   $$Tijdens het hoogtepunt van de plaag hebben boeren geprobeerd de veldmuizen te verdrijven door het land tijdelijk onder water te zetten. Het zou echter beter zijn om de veldmuizen te bestrijden voordat er overlast en schade is.$$, 'inline'),
  ('faafa1c3-c260-4e17-9012-e2aa19b50f52', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$scenario: populatiegroei van 10 naar 6000 veldmuizen, met of zonder vroeg ingrijpen (uitwerkbijlage)$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context4.png$$,
   $$Veronderstel dat in een bepaald gebied begin mei 10 veldmuizen leven en dat dit aantal zal stijgen tot 6000 individuen begin november.
Zou in dit gebied al in een vroeg stadium worden ingegrepen, dan kan dit het aantal individuen in november aanzienlijk beperken. Een mogelijkheid is om al begin juli het land enkele dagen onder water te zetten, waardoor de populatie halveert.
In de uitwerkbijlage is een assenstelsel getekend. Om een beeld te geven van het verschil tussen wel en niet ingrijpen, kan in dit assenstelsel het verloop van de aantallen veldmuizen in de twee beschreven situaties vergeleken worden.$$, 'inline'),
  ('75838252-f735-4c77-b0ba-2d49f5d32d97', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$uitwerkbijlage bij vraag 32: leeg assenstelsel voor het aantal veldmuizen per maand$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context5.png$$,
   $$Uitwerkbijlage bij vraag 32: leeg assenstelsel met op de x-as de maanden april tot en met november en op de y-as het aantal veldmuizen in een bepaald gebied (0-7000), met een legenda voor ‘zonder ingreep’ (doorgetrokken lijn) en ‘met ingreep’ (gestreepte lijn), in te vullen door de leerling.$$, 'uitwerkbijlage'),
  ('f038b37d-1d87-496f-a05e-fdc55d5c5721', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$vraag: is bestrijding op het hoogtepunt van de plaag beter dan afwachten?$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context6.png$$,
   $$Het is de vraag of bestrijding door het onder water zetten van het land op het hoogtepunt van de plaag beter is dan de plaag op zijn beloop laten en de winter afwachten.$$, 'inline'),
  ('47a486f5-4b6e-47d7-b596-d04464a2529b', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$bromadiolon is een vitamine-K-antagonist; vitamine K is nodig voor trombinevorming$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context7.png$$,
   $$Boeren kunnen de veldmuizenpopulatie ook terugdringen met muizengif zoals bromadiolon, een vitamine-K-antagonist.
Vitamine K is nodig voor de vorming van trombine in het bloed.$$, 'inline'),
  ('3fc2afe8-53d1-4a29-bfe5-0bb1bd8b5eae', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$meer stikstofverbindingen in oppervlaktewater bij veel muizen; drie verklarende uitspraken$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context8.png$$,
   $$In een gebied met grote aantallen muizen komen meer stikstofverbindingen in het oppervlaktewater terecht. In sommige gebieden met muizenschade was de concentratie stikstof in de sloten met 70% toegenomen. Er worden drie uitspraken gedaan om dit te verklaren:
1 Veldmuizen bevorderen door hun gegraaf de ammonificatie en nitrificatie;
2 Veldmuizen verspreiden poep en urine met daarin stikstofverbindingen;
3 Veldmuizen tasten het gras aan waardoor het minder nitraat opneemt.$$, 'inline'),
  ('fec7a129-c8e3-409f-9f46-ccae1d92f04d', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$onderzoek naar invloed van openheid landschap en drooglegging op muizenschade (afbeelding 3 ⚠️)$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context9.png$$,
   $$In het onderzoek naar het ontstaan van veldmuizenplagen is bepaald wat de invloed is van de openheid van het landschap (hoe ver je kunt kijken zonder dat er struiken en bomen in het zicht staan) en de drooglegging (verlaging van het grondwaterpeil ten opzichte van het maaiveld).
Deze variabelen staan in een database met landschapsgegevens.
In deze database is heel Nederland opgedeeld in zeshoeken met een grootte van 1 km². Van alle zeshoeken met dezelfde openheids- en droogleggingsklasse is bepaald in hoeveel procent hiervan melding was gemaakt van muizenschade.
Het resultaat is weergegeven in het diagram van afbeelding 3.
afbeelding 3: ⚠️ CONTROLEREN: het diagram van afbeelding 3 (percentage meldingen van muizenschade per klasse van openheid en drooglegging) ontbreekt in het originele examen-PDF-bestand; alleen het bijschrift ‘afbeelding 3’ staat op deze plek, de grafiek zelf is niet aanwezig in het brondocument.$$, 'inline'),
  ('e759296d-d826-4e2e-913e-488c042aabe3', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$twee beweringen over de invloed van drooglegging en openheid op muizenschade$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context10.png$$,
   $$Twee beweringen naar aanleiding van dit onderzoek zijn:
1 De drooglegging is als factor belangrijker voor het ontstaan van schade door veldmuizen dan de openheid van het grasland.
2 Schade in een klein en door struiken en bomen beschut grasland wordt eerder opgemerkt dan schade in een weids grasland.$$, 'inline'),
  ('166e29d7-044e-464d-a12a-bd506630a07d', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$specialisten en generalisten als predatoren van veldmuizen; heterogeen landschap als maatregel$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context11.png$$,
   $$Ecologen onderscheiden twee typen predatoren:
1 Specialisten, zoals de wezel, die slechts op een of enkele prooisoorten prederen;
2 Generalisten, zoals de vos, die allerlei prooisoorten eten en makkelijk overschakelen.
Veldmuizen worden gegeten door zowel specialisten als generalisten.
In Nederland en Duitsland komen muizenplagen vooral voor in grote uitgestrekte graslanden. Een ingrijpende ecologische maatregel om deze plagen te voorkomen, is het omvormen van deze graslanden tot een heterogeen landschap bestaande uit kleinere graslanden afgewisseld met akkerbouwland, heggetjes en bosjes.$$, 'inline'),
  ('1b1ff45f-58c3-4c9a-894f-f67c7074afa4', '9faa41fd-4464-42d1-8725-7f7bbdb976da', $$maatregelen tegen veldmuizenplaag: nestkasten en bodembewerking$$,
   $$biologie-vwo-2018-ii-wat-te-doen-aan-de-muizenplagen-context12.png$$,
   $$Een melkveehouder in Friesland wil zijn percelen grasland enkele keren maaien om het gras als hooi op te slaan voor de winter. Maatregelen die ecologen voorstellen tegen een veldmuizenplaag zijn onder andere:
1 Nestkasten plaatsen, zodat roofvogels aangetrokken worden;
2 Bodembewerking, zoals het machinaal omploegen van het grasland.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('ee2a2066-5061-4cdc-af93-96786dd6d56b', '8820e42f-4d5f-44d2-986b-d39ecc504d89', 1,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Zelfregulatie van het organisme"}]'::jsonb,
   '["endothermie", "oppervlakte-inhoudverhouding", "warmteverlies", "thermoregulatie"]'::jsonb,
   $$Verklaren waarom een grote oppervlakte-inhoudverhouding endothermie ongunstig maakt voor kleine vissoorten.$$,
